import sys
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]
    factors = {}

    for idx, x in enumerate(arr):
        d = 2
        while d * d <= x:
            if x % d == 0:
                c = 0
                while x % d == 0:
                    x //= d
                    c += 1
                factors.setdefault(d, []).append((idx, c))
            d += 1
        if x > 1:
            factors.setdefault(x, []).append((idx, 1))

    ans = 1
    for p, occurrences in factors.items():
        vals = [0] * (n - 1)
        total = 0
        for i, a in occurrences:
            vals[i] = a
            total += a

        powers = [1] * (total + 1)
        for j in range(1, total + 1):
            powers[j] = powers[j - 1] * p % MOD

        # h is the current height above the minimum so far. Each dp value
        # sums p^(sum of the normalized heights) over paths reaching h.
        dp = {0: 1}
        edges_seen = 0
        for a in vals:
            nd = {}
            for h, ways_weighted in dp.items():
                if a == 0:
                    nd[h] = (nd.get(h, 0) + ways_weighted * powers[h]) % MOD
                else:
                    y = h + a
                    nd[y] = (nd.get(y, 0) + ways_weighted * powers[y]) % MOD

                    y = h - a
                    if y >= 0:
                        nd[y] = (nd.get(y, 0) + ways_weighted * powers[y]) % MOD
                    else:
                        # A new minimum is reached. All previous heights
                        # increase by -y relative to the new minimum.
                        shift = -y
                        multiplier = pow(p, shift * (edges_seen + 1), MOD)
                        nd[0] = (nd.get(0, 0) + ways_weighted * multiplier) % MOD
            dp = nd
            edges_seen += 1

        ans = ans * (sum(dp.values()) % MOD) % MOD

    print(ans)

if __name__ == '__main__':
    solve()

