import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:]
    limit = 100000

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    phi = list(range(limit + 1))
    for p in range(2, limit + 1):
        if phi[p] == p:
            for x in range(p, limit + 1, p):
                phi[x] -= phi[x] // p

    weighted_count = [0] * (limit + 1)
    answer = 0
    weight = 1
    output = []

    for value in values:
        y = value
        factors = []
        while y > 1:
            p = spf[y]
            exponent = 0
            while y % p == 0:
                y //= p
                exponent += 1
            factors.append((p, exponent))

        divisors = [1]
        for p, exponent in factors:
            previous = divisors[:]
            power = 1
            for _ in range(exponent):
                power *= p
                divisors.extend(d * power for d in previous)

        contribution = 0
        for d in divisors:
            contribution += phi[d] * weighted_count[d]
            weighted_count[d] = (weighted_count[d] + weight) % MOD

        answer = (2 * answer + contribution) % MOD
        output.append(str(answer))
        weight = weight * 2 % MOD

    sys.stdout.write("\n".join(output))

if __name__ == '__main__':
    solve()

