from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        first_val = second_val = 0
        first_id = -1
        gain = [0] * m
        base = 0
        for r in range(1, n + 1):
            for a, idx in by_right[r]:
                if a > first_val:
                    second_val = first_val
                    first_val, first_id = a, idx
                elif a > second_val:
                    second_val = a
            base += r - first_val
            if first_id != -1 and first_val > second_val:
                gain[first_id] += first_val - second_val
        return base + max(gain)

