import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = []
    for _ in range(m):
        edges.append((next(it) - 1, next(it) - 1, next(it)))

    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e, 0))
            closed[e] = True
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            dist[a][b] = dist[b][a] = c

    # Initial all-pairs shortest paths in the graph after every closure.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    # In reverse order, each closure becomes an edge insertion.
    for t, a, b in reversed(queries):
        if t == 2:
            value = dist[a][b]
            answers.append(str(value if value < inf else -1))
        else:
            u, v, w = edges[a]
            to_u = [dist[i][u] for i in range(n)]
            to_v = [dist[i][v] for i in range(n)]
            for i in range(n):
                row_i = dist[i]
                iu = to_u[i]
                iv = to_v[i]
                for j in range(n):
                    candidate = min(iu + w + to_v[j], iv + w + to_u[j])
                    if candidate < row_i[j]:
                        row_i[j] = candidate

    sys.stdout.write("\n".join(reversed(answers)))

if __name__ == "__main__":
    main()

