import math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    processes = [tuple(data[i:i + 4]) for i in range(2, len(data), 4)]

    def minimum_cost(k, a, p, b, q):
        # x >= ceil(k/a) already reaches k with S machines alone.
        upper = (k + a - 1) // a
        best = p * upper
        period = b // math.gcd(a, b)

        # For x below upper and fixed residue modulo period, the required
        # number of T machines changes linearly as x advances by period.
        # Thus the minimum is at one of the two endpoints of that residue's
        # feasible interval.
        for r in range(min(period, upper)):
            last = r + ((upper - 1 - r) // period) * period
            for x in (r, last):
                y = (k - a * x + b - 1) // b
                cost = p * x + q * y
                if cost < best:
                    best = cost
        return best

    def feasible(k):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

