class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        C = [[0] * (n + 1) for _ in range(n + 1)]
        C[0][0] = 1
        for i in range(1, n + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        ans = 0
        for target in range(1, n + 1):
            steps = 0
            x = target
            while x != 1:
                x = x.bit_count()
                steps += 1
            if steps > k - 1:
                continue
            ones = 0
            count = 0
            for i, ch in enumerate(s):
                remaining = n - i - 1
                if ch == '1':
                    need = target - ones
                    if 0 <= need <= remaining:
                        count += C[remaining][need]
                    ones += 1
            ans = (ans + count) % MOD
        return ans

