from collections import deque

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    N, M, Q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(M)]
    queries = [(next(it), next(it)) for _ in range(Q)]
    B = 1
    while B < N: B <<= 1
    base = 2 * B
    out = [[] for _ in range(base)]
    # Range propagation trees: downward for endpoint -> range, upward for range -> endpoint.
    for v in range(1, B):
        out[v].append((2*v, 0)); out[v].append((2*v+1, 0))
    for v in range(B, 2*B):
        if v > 1: out[v].append((v//2, 0))
    def cover(l, r):
        l += B; r += B
        z=[]
        while l < r:
            if l&1: z.append(l); l+=1
            if r&1: r-=1; z.append(r)
            l//=2; r//=2
        return z
    ans=[]
    for L,R in queries:
        g=[[] for _ in range(base)]
        # Internal range propagation edges
        for v in range(1,B):
            g[v].append((2*v,0)); g[v].append((2*v+1,0))
        for v in range(B+N,2*B):
            pass
        for v in range(B+1,2*B):
            g[v].append((v//2,0))
        for a,b in people[L-1:R]:
            x,y=sorted((a-1,b-1))
            u=B+(a-1); v=B+(b-1)
            g[u].append((v,0)); g[v].append((u,0))
            nodes=cover(x+1,y)
            if a < b: # interior higher: endpoint -> interior with strict increase
                for w in nodes: g[u].append((w,1))
            else: # interior lower: interior -> endpoint
                for w in nodes: g[w].append((u,1))
        dist=[0]*base
        q=deque(range(base)); inq=bytearray([1])*base
        cnt=[0]*base
        ok=True
        while q and ok:
            u=q.popleft(); inq[u]=0
            for v,w in g[u]:
                nd=dist[u]+w
                if nd>dist[v]:
                    dist[v]=nd; cnt[v]=cnt[u]+1
                    if cnt[v]>=base:
                        ok=False; break
                    if not inq[v]: q.append(v); inq[v]=1
        ans.append('Yes' if ok else 'No')
    print('\n'.join(ans))
