import sys, heapq

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    graph = [row.decode() for row in data[1:1 + n]]
    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []

    # Palindromes of length 0 and 1 are the centers of every answer.
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                heapq.heappush(heap, (1, i, j))

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for a in range(n):
        for b, ch in enumerate(graph[a]):
            if ch != '-':
                k = ord(ch) - 97
                outgoing[a][k].append(b)
                incoming[b][k].append(a)

    max_finite = 1 if n > 1 or any(ch != '-' for row in graph for ch in row) else 0
    while heap:
        d, i, j = heapq.heappop(heap)
        if dist[i][j] != d:
            continue
        nd = d + 2
        # No currently finite answer can be improved by this value or higher.
        if max_finite <= nd:
            continue
        for k in range(26):
            left = incoming[i][k]
            right = outgoing[j][k]
            for a in left:
                row = dist[a]
                for b in right:
                    if nd < row[b]:
                        row[b] = nd
                        if nd > max_finite:
                            max_finite = nd
                        heapq.heappush(heap, (nd, a, b))

    print('\n'.join(' '.join('-1' if x == inf else str(x) for x in row) for row in dist))

solve()

