from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = set(range(1, n + 1, 2))
        evens = set(range(2, n + 1, 2))
        ans = []
        last_parity = None

        for pos in range(n):
            chosen = None
            for x in sorted(odds | evens):
                parity = x & 1
                if last_parity is not None and parity == last_parity:
                    continue

                remaining_odds = len(odds) - (parity == 1)
                remaining_evens = len(evens) - (parity == 0)
                remaining_slots = n - pos - 1

                if remaining_slots:
                    first_parity = 1 - parity
                    required_odds = (remaining_slots + (first_parity == 1)) // 2
                    required_evens = remaining_slots - required_odds
                else:
                    required_odds = required_evens = 0

                if (remaining_odds == required_odds and
                        remaining_evens == required_evens):
                    ways = factorial(remaining_odds) * factorial(remaining_evens)
                else:
                    ways = 0

                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            ans.append(chosen)
            if chosen & 1:
                odds.remove(chosen)
            else:
                evens.remove(chosen)
            last_parity = chosen & 1

        return ans

