class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        cells = m * n

        # Sum of Manhattan distances over all unordered cell pairs.
        # For each row-coordinate pair, there are n^2 choices of columns;
        # similarly, each column-coordinate pair has m^2 row choices.
        distance_sum = (
            n * n * (m**3 - m) // 6
            + m * m * (n**3 - n) // 6
        )

        # Each pair appears in C(cells - 2, k - 2) arrangements.
        ways = 1
        for x in range(cells - k + 1, cells - 1):
            ways = ways * x % MOD
        denominator = 1
        for x in range(1, k - 1):
            denominator = denominator * x % MOD
        ways = ways * pow(denominator, MOD - 2, MOD) % MOD

        return (distance_sum % MOD) * ways % MOD

