class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # Each choice fixes one mirrored pair (or the center digit).
        # Its coefficient is its contribution to the number modulo k.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for j in range(m):
            other = n - 1 - j
            value = powers[j]
            if j != other:
                value += powers[other]
            coeff.append(value % k)

        # dp[i] is a bitmask of residues achievable by variables i..m-1.
        dp = [0] * (m + 1)
        dp[m] = 1  # Only residue 0 is achievable with no digits left.
        for i in range(m - 1, -1, -1):
            mask = 0
            for digit in range(10):
                shift = coeff[i] * digit % k
                for residue in range(k):
                    if (dp[i + 1] >> residue) & 1:
                        mask |= 1 << ((residue + shift) % k)
            dp[i] = mask

        # Greedily maximize each digit, retaining only choices that can be
        # completed to a total residue of zero.
        digits = []
        remainder = 0
        for i, c in enumerate(coeff):
            smallest = 1 if i == 0 else 0
            for digit in range(9, smallest - 1, -1):
                needed = (-remainder - c * digit) % k
                if (dp[i + 1] >> needed) & 1:
                    digits.append(str(digit))
                    remainder = (remainder + c * digit) % k
                    break

        half = ''.join(digits)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

