from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        # next_greater[i] is the first index to the right with value > nums[i].
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            if stack:
                next_greater[i] = stack[-1]
            stack.append(i)

        levels = n.bit_length()
        jump = [next_greater] + [[n] * n for _ in range(levels - 1)]
        # cost[b][i] is the cost of all complete maximum-constant runs
        # traversed by taking 2**b next-greater links from i.
        cost = [[0] * n for _ in range(levels)]
        for i in range(n):
            j = next_greater[i]
            cost[0][i] = nums[i] * (j - i) - (prefix[j] - prefix[i])

        for b in range(1, levels):
            prev_jump = jump[b - 1]
            for i in range(n):
                middle = prev_jump[i]
                if middle < n:
                    jump[b][i] = prev_jump[middle]
                    cost[b][i] = cost[b - 1][i] + cost[b - 1][middle]
                else:
                    jump[b][i] = n
                    cost[b][i] = cost[b - 1][i]

        def window_cost(left: int, right: int) -> int:
            pos = left
            result = 0
            for b in range(levels - 1, -1, -1):
                destination = jump[b][pos]
                if destination <= right:
                    result += cost[b][pos]
                    pos = destination
            # The final prefix-maximum run ends at right.
            return result + nums[pos] * (right - pos + 1) - (prefix[right + 1] - prefix[pos])

        answer = 0
        left = 0
        for right in range(n):
            while left <= right and window_cost(left, right) > k:
                left += 1
            answer += right - left + 1
        return answer

