from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # In execution order, f_i before f_j is preferable when
    # (A_j - 1) * B_i >= (A_i - 1) * B_j.
    # Thus functions are processed by increasing (A - 1) / B.
    def compare(x, y):
        lhs = (x[0] - 1) * y[1]
        rhs = (y[0] - 1) * x[1]
        return (lhs > rhs) - (lhs < rhs)

