values = A + B + C
all_cards = (1 << len(values)) - 1

# tm and am encode the cards in each player's hand; all other cards
# are on the table. Turn 0 is Takahashi, turn 1 is Aoki.
@lru_cache(None)
def winning(tm, am, turn):
    hand = tm if turn == 0 else am
    if hand == 0:
        return False

    table = all_cards ^ (tm | am)
    while hand:
        card = hand & -hand
        hand -= card
        value = values[card.bit_length() - 1]

        # Put this card on the table, without taking another card.
        if turn == 0:
            nt, na, next_turn = tm ^ card, am, 1
        else:
            nt, na, next_turn = tm, am ^ card, 0
        if not winning(nt, na, next_turn):
            return True

        # Or take any lower-valued card now on the table.
