from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        a_pos = occurrences(a)
        b_pos = occurrences(b)
        c_pos = occurrences(c)
        a_ends = [pos + len(a) for pos in a_pos]

        best = n + 1
        for mid in b_pos:
            if a:
                i = bisect_right(a_ends, mid) - 1
                if i < 0:
                    continue
                left = a_pos[i]
            else:
                left = mid

            if c:
                i = bisect_left(c_pos, mid + len(b))
                if i == len(c_pos):
                    continue
                right = c_pos[i] + len(c)
            else:
                right = mid + len(b)

            best = min(best, right - left)

        return -1 if best == n + 1 else best

