import sys

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0]); p = 1
    out = []
    for _ in range(t):
        n = int(data[p]); p += 1
        a = data[p].decode(); p += 1
        b = data[p].decode(); p += 1
        xs = [i for i, c in enumerate(a) if c == '1']
        ys = [i for i, c in enumerate(b) if c == '1']
        if len(xs) < len(ys):
            out.append('-1'); continue

        def feasible(d):
            # Every initial piece must be able to end on some required square.
            j = 0
            for x in xs:
                while j < len(ys) and ys[j] < x - d:
                    j += 1
                if j == len(ys) or ys[j] > x + d:
                    return False
            # Assign a distinct initial piece to each required square.
            i = 0
            for y in ys:
                while i < len(xs) and xs[i] < y - d:
                    i += 1
                if i == len(xs) or xs[i] > y + d:
                    return False
                i += 1
            return True

        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid): hi = mid
            else: lo = mid + 1
        out.append(str(lo))
    sys.stdout.write('\n'.join(out))

