from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = Counter(nums)
        for x in sorted(freq, reverse=True):
            remainder = total - x
            if remainder % 2:
                continue
            special_sum = remainder // 2
            needed = 2 if special_sum == x else 1
            if freq.get(special_sum, 0) >= needed:
                return x
        # The input guarantees that at least one potential outlier exists.
        raise ValueError("No potential outlier")

