class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(value == 0 for value in nums):
            return 0

        # Bit s indicates that sum s is achievable from processed queries
        # that cover this index.
        reachable = [1] * n
        masks = [(1 << (value + 1)) - 1 for value in nums]

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                reachable[i] = (reachable[i] | (reachable[i] << value)) & masks[i]
            if all((reachable[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

