class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        prime = [True] * 10000
        prime[0] = prime[1] = False
        for p in range(2, 100):
            if prime[p]:
                for x in range(p * p, 10000, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        length = len(str(n))
        low = 1 if length == 1 else 10 ** (length - 1)
        high = 10 ** length - 1
        place_values = [10 ** i for i in range(length)]

        # Pay for the initial value and then for each newly reached value.
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10
                for delta in (-1, 1):
                    new_digit = digit + delta
                    if not 0 <= new_digit <= 9:
                        continue
                    neighbor = value + delta * place
                    if not low <= neighbor <= high or prime[neighbor]:
                        continue
                    new_cost = cost + neighbor
                    if new_cost < dist.get(neighbor, float("inf")):
                        dist[neighbor] = new_cost
                        heapq.heappush(heap, (new_cost, neighbor))

        return -1

