from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        # Let i be the first subarray length and d the second's length.
        # The second-prefix-of-third condition compares nums[i:] with nums[i+d:].
        # Scan each fixed offset d backwards, maintaining that LCP.
        for d in range(1, n):
            common = 0
            for i in range(n - d - 1, 0, -1):
                if nums[i] == nums[i + d]:
                    common += 1
                else:
                    common = 0

                first_prefix_of_second = d >= i and z[i] >= i
                second_prefix_of_third = common >= d
                if first_prefix_of_second or second_prefix_of_third:
                    answer += 1

        return answer

