from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        targets = set(targetIndices)
        inf = len(targetIndices) + 1
        # dp[j]: minimum targeted indices that must be retained to match
        # the first j characters of pattern using the source scanned so far.
        dp = [inf] * (len(pattern) + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if i in targets else 0
            # Descending order ensures this source character is used at most once.
            for j in range(len(pattern) - 1, -1, -1):
                if ch == pattern[j]:
                    dp[j + 1] = min(dp[j + 1], dp[j] + cost)

        return len(targetIndices) - dp[len(pattern)]

