class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse each edge so a traversal from 0 finds nodes that can reach 0.
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        weights = sorted({w for _, _, w in edges})

        def feasible(limit: int) -> bool:
            seen = bytearray(n)
            seen[0] = 1
            stack = [0]
            reached = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = 1
                        reached += 1
                        stack.append(u)
            return reached == n

        if not feasible(weights[-1]):
            return -1

        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

